using FlexExtractor;
using System.Diagnostics;
static partial class Cases {
 static void Junction(string alias,string target){using var p=Process.Start(new ProcessStartInfo("cmd.exe"){UseShellExecute=false,RedirectStandardOutput=true,ArgumentList={"/c","mklink","/J",alias,target}})!;var output=p.StandardOutput.ReadToEnd();p.WaitForExit();Program.Check(p.ExitCode==0,"junction fixture failed: "+output);}
 static (Config Config,string Destination) ExpiredOwned(){var c=Cfg(Fresh());c.SizeStableChecks=0;c.KeepDays=14;var s=Source(c);File.SetCreationTimeUtc(s,DateTime.UtcNow.AddDays(-3));File.SetLastWriteTimeUtc(s,DateTime.UtcNow.AddDays(-3));Scan(c);c.KeepDays=1;return(c,Directory.GetFiles(c.DispenseItems[0].SaveFolder,"Request*.xml").Single());}
 public static void TestReviewSourceJunctionPurgePreservesSource(){var(c,dest)=ExpiredOwned();var alias=Path.Combine(Path.GetDirectoryName(c.WatchRoot)!,"alias");Junction(alias,c.DispenseItems[0].SaveFolder);try{c.WatchRoot=alias;bool rejected=false;try{Scan(c,"purge");}catch(InvalidDataException){rejected=true;}Program.Check(File.Exists(dest),"purge deleted current source via junction");Program.Check(rejected,"unsafe source was not rejected before purge");}finally{Directory.Delete(alias);}}
 public static void TestReviewSourceAncestorJunctionRejectedByValidation(){var(c,dest)=ExpiredOwned();var alias=Path.Combine(Path.GetDirectoryName(c.WatchRoot)!,"alias-parent");Junction(alias,c.DispenseItems[0].SaveFolder);try{c.WatchRoot=Path.Combine(alias,"missing-child");Rejected(()=>c.Validate());Program.Check(File.Exists(dest),"validation mutated source");}finally{Directory.Delete(alias);}}
 public static void TestReviewSourceOfflineUncPurgeDoesNotProbe(){var(c,dest)=ExpiredOwned();c.WatchRoot=@"\\192.0.2.1\offline-review";c.WorkerTimeoutSec=2;var watch=Stopwatch.StartNew();c.Validate();Program.Check(watch.Elapsed.TotalSeconds<1,"GUI validation probed UNC");using var lease=new OwnerLease();var r=WorkerRunner.RunAsync(lease,c,"purge",DateTime.UtcNow,CancellationToken.None).GetAwaiter().GetResult();Program.Check(r.Deleted==1&&r.Failed==0&&!File.Exists(dest),"UNC offline blocked local purge: "+string.Join(" | ",r.Messages));Program.Check(watch.Elapsed.TotalSeconds<4,"purge waited on source network");}
}
